-- ---------------------------------------------
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Ken Watanabe', 'ken-watanabe', 'Ken Watanabe is a preeminent Japanese actor of extraordinary range and international distinction whose luminous career bridges the worlds of classical Japanese theater, prestigious stage productions, and globally celebrated Hollywood blockbusters with effortless, magnetic authority. Born in 1959 in Uonuma, Niigata Prefecture, Japan, Watanabe developed a formidable foundation in dramatic performance through years of stage theater before ascending to starring roles in Japanese television and cinema. His international breakthrough arrived with absolute cinematic force in Edward Zwick\'s sweeping 2003 samurai epic The Last Samurai alongside Tom Cruise, where his dignified, deeply human portrayal of the noble warrior Katsumoto earned him an Academy Award nomination for Best Supporting Actor — making him only the second Japanese actor ever nominated in that category. He continued to resonate in Western productions with his portrayal of Ra\'s al Ghul in Christopher Nolan\'s Batman Begins (2005), commanding presence in Nolan\'s labyrinthine sci-fi masterpiece Inception (2010) as the billionaire Saito, and a pivotal appearance in the Godzilla MonsterVerse series as Monarch\'s Dr. Ichiro Serizawa, whose reverent belief in Godzilla as a divine natural force anchors the franchise\'s philosophical heart. On Japanese stages and screens he has performed in acclaimed productions of Shakespeare\'s King Lear. His artistry is defined by deep stillness, gravitas, and an extraordinary ability to convey profound moral weight through subtle expression — qualities that have made him the most internationally recognized Japanese actor of his generation.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Tom Hiddleston', 'tom-hiddleston', 'Thomas William Hiddleston is a supremely versatile and intellectually captivating British actor whose dynamic stage presence, classical Shakespearean training, and effortless command of complex, morally nuanced characters have established him as one of the most compelling and charismatic performers of his generation. Born in 1981 in Westminster, London, Hiddleston was educated at Eton College and later honed his exceptional dramatic instincts at Pembroke College, Cambridge, before earning his postgraduate Master of Arts degree from the Royal Academy of Dramatic Art (RADA). His formative years were richly steeped in classical theater, including acclaimed stage productions of Othello, Ivanov, and Coriolanus with the Royal Shakespeare Company and the National Theatre. His electric, career-defining international breakthrough arrived through director Kenneth Branagh\'s 2011 superhero epic Thor, where Hiddleston\'s magnetic, emotionally layered portrayal of the Asgardian god of mischief, Loki, immediately captivated global audiences and critics alike. Reprising the role across multiple Marvel Cinematic Universe films and Disney+\'s acclaimed Loki series, Hiddleston transformed a comic book antagonist into a deeply empathetic, Shakespearean tragedy of identity, belonging, and redemption. Beyond the MCU, he demonstrated remarkable dramatic breadth in Steven Spielberg\'s War Horse (2011), Guillermo del Toro\'s gothic romance Crimson Peak (2015), and as Jonathan Pine in The Night Manager BBC series (2016), earning a Golden Globe Award. His portrayal of the tracker James Conrad in Kong: Skull Island showcased his full-bodied physical charisma in an action-adventure setting.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Brie Larson', 'brie-larson', 'Brianne Sidonie Desaulniers, known professionally as Brie Larson, is a fiercely talented, critically acclaimed, and pioneering American actress, filmmaker, and activist whose extraordinary career trajectory from childhood performer to Academy Award-winning dramatic actress to Marvel superhero embodies a rare combination of artistic fearlessness and cultural significance. Born in 1989 in Sacramento, California, Larson began studying acting at the American Conservatory Theater at the age of six, developing a precocious emotional maturity and technical command that would define her work for decades. She built a solid foundation in comedy through recurring roles in television before pivoting into dramatic film work of increasing intensity and vulnerability. Her transformative breakthrough arrived with Ryan Fleck and Anna Boden\'s 2013 independent film Short Term 12, in which her heartbreaking portrayal of a compassionate residential facility supervisor navigating personal trauma earned universal critical acclaim. The role of Joy in Lenny Abrahamson\'s 2015 psychological thriller Room delivered her the Academy Award for Best Actress, the Golden Globe Award, and the BAFTA Award — making her one of the most decorated actresses of her generation. She entered the Marvel Cinematic Universe as Carol Danvers, the first female lead superhero, in Captain Marvel (2019), which grossed over one billion dollars globally. Her role as journalist Mason Weaver in Kong: Skull Island — drawn to the island\'s mystery and forming an instinctive kinship with Kong — showcased her natural command of action blockbusters while maintaining her character\'s moral integrity.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Millie Bobby Brown', 'millie-bobby-brown', 'Millie Bobby Brown is a phenomenally gifted British-American actress, producer, and entrepreneur who has risen with astonishing velocity from a precocious child actress to a globally celebrated creative force, redefining what young performers can achieve in both prestige television and blockbuster cinema. Born in 1994 in Marbella, Spain, to English parents, Brown displayed irrepressible dramatic instincts from early childhood and began performing with professional commitment from the age of nine. Following minor television roles in Once Upon a Time and Grey\'s Anatomy, she delivered the performance that would permanently alter her career trajectory: her portrayal of Eleven in Netflix\'s sensation Stranger Things (2016), a telekinetically gifted girl who escapes a government experimentation program. The role earned her an Emmy Award nomination — making her the youngest nominee in the Drama Supporting Actress category in Emmy history — global superstardom, and a devoted, multi-generational fanbase. She embodied the character\'s emotional arc across five seasons with a depth and consistency that transcended her age, requiring her to convey trauma, love, loss, and supernatural power through minimal dialogue but maximum emotional precision. She crossed into film franchises through the Godzilla MonsterVerse, playing the teenage Madison Russell, daughter of a Monarch bioacoustics scientist, across Godzilla: King of the Monsters (2019) and Godzilla vs. Kong (2021). She further expanded her creative ambitions by producing and starring in the Enola Holmes Netflix franchise as Sherlock Holmes\'s whip-smart younger sister. TIME magazine named her one of the 100 most influential people in the world.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Kyle Chandler', 'kyle-chandler', 'Kyle Chandler is a quietly magnetic, emotionally precise, and deeply respected American actor whose long, distinguished career in both prestige television and feature film has established him as one of Hollywood\'s most reliably excellent character-driven performers. Born in 1965 in Buffalo, New York, Chandler grew up in Loganville, Georgia, and studied acting at the University of Georgia before training at the Lee Strasberg Theatre and Film Institute in New York. After building a steady television presence through the 1990s, his career ascended to iconic heights with his career-defining role as Coach Eric Taylor in NBC\'s critically revered drama Friday Night Lights (2006–2011). His portrayal of the quietly determined, morally steadfast Texas high school football coach earned him a Primetime Emmy Award for Outstanding Lead Actor in a Drama Series in 2011 and cemented his reputation for delivering emotionally authentic, understated performances of remarkable depth. He continued his prestige television ascendancy with pivotal roles in the political thriller series Bloodline (2015–2017), earning his second Emmy nomination. On the big screen, Chandler brought notable dramatic gravitas to films including Martin Scorsese\'s The Wolf of Wall Street (2013) as FBI agent Patrick Denham, and as the Monarch field leader Dr. Mark Russell in Godzilla: King of the Monsters (2019) and Godzilla vs. Kong (2021). His approach — marked by psychological interiority, quiet confidence, and the subtle conveyance of moral complexity — makes him one of contemporary American acting\'s most consistent and compelling presences.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Alexander Skarsgård', 'alexander-skarsgard', 'Alexander Johan Hjalmar Skarsgård is a strikingly versatile, physically commanding, and intellectually adventurous Swedish-American actor of exceptional range whose career has spanned indie art-house films, prestige television, and global blockbusters with effortless authority and an electrifying screen magnetism. Born in 1976 in Stockholm, Sweden, he is the eldest son of legendary Swedish actor Stellan Skarsgård, and grew up surrounded by the theatrical world that would shape his own artistic sensibility. He served in the Swedish military before studying at Marymount Manhattan College in New York, channeling his discipline and intensity into his acting craft. His American breakthrough came through the HBO vampire drama True Blood (2008–2014), where his nuanced portrayal of the ancient, powerful vampire Eric Northman — imperious, darkly humorous, and haunted by centuries of existence — earned him dedicated fan devotion and critical recognition. He demonstrated astonishing dramatic range in Jean-Marc Vallée\'s HBO limited series Big Little Lies (2017), where his chilling portrayal of the charming, abusive Perry Wright earned him a Primetime Emmy Award, a Golden Globe Award, and a Screen Actors Guild Award — cementing his place among television\'s finest dramatic actors. On the big screen, Skarsgård has brought physical grandeur to blockbuster roles in The Legend of Tarzan (2016) and Godzilla vs. Kong (2021) as the Hollow Earth expert Dr. Nathan Lind, while demonstrating intimate dramatic depth in The Northman (2022), Robert Eggers\' brutal Norse epic in which he plays the Viking prince Amleth. His artistry is defined by unpredictable range, physical commitment, and magnetic intensity.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Rebecca Hall', 'rebecca-hall', 'Rebecca Hall is a brilliantly cerebral, chameleonic, and deeply literary British-American actress of formidable intelligence and emotional precision whose distinguished career across theater, film, and television has established her as one of the most consistently compelling dramatic performers of her generation. Born in 1982 in London, England, Hall is the daughter of renowned British theater director Peter Hall and American singer Maria Ewing, immersing her in the arts from birth. She studied English Literature at Pembroke College, Cambridge, before training at the Royal Academy of Dramatic Art, building a rich foundation in classical theater that informs every role she undertakes with a distinctive intellectual depth. Her breakthrough arrived in Christopher Nolan\'s The Prestige (2006) as the tragic magician\'s wife Julia McCullough, immediately announcing a performer of unusual luminosity. She then demonstrated the full breadth of her gifts in Woody Allen\'s Vicky Cristina Barcelona (2008), earning a Golden Globe nomination for her portrayal of the intellectually cautious Vicky caught between romantic certainty and passionate chaos. She delivered a career-best performance in Christine (2016), portraying real-life television news reporter Christine Chubbuck with devastating, psychological richness. She extended her filmography into writing and directing with Passing (2021), her critically acclaimed debut feature film examining race, identity, and desire in 1920s Harlem, earning nominations for the BAFTA Award for Outstanding British Film. As Dr. Ilene Andrews in Godzilla vs. Kong and Godzilla x Kong: The New Empire, Hall brought authentic scientific warmth and maternal conviction to the MonsterVerse\'s human heart. Her artistry is defined by intellectual rigor and emotional courage.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Brian Tyree Henry', 'brian-tyree-henry', 'Brian Tyree Henry is an explosively gifted, comedically masterful, and dramatically devastating American actor of extraordinary versatility whose rapid ascent from stage actor to Emmy-nominated television star to Oscar-nominated film presence marks one of contemporary Hollywood\'s most compelling artistic trajectories. Born in 1982 in Fayetteville, North Carolina, Henry was raised with deep emotional ties to his community before pursuing his passion at Morehouse College in Atlanta and graduating from the Yale School of Drama in 2009 — one of America\'s most demanding and prestigious actor training programs. His theater career blossomed through acclaimed Broadway productions including The Book of Mormon and Lobby Hero, where his natural comedic genius and emotional depth earned industry recognition. His extraordinary breakthrough arrived through Donald Glover\'s groundbreaking FX comedy-drama Atlanta (2016–2022), where Henry\'s portrayal of Alfred Miles, a rising Atlanta rapper navigating the treacherous intersection of street credibility and artistic ambition, earned him a Primetime Emmy Award nomination and instant cultural icon status. The performance\'s tonal complexity — shifting effortlessly between hilarious deadpan comedy and profound emotional vulnerability — demonstrated a singular artistic intelligence. He delivered a devastating Oscar-nominated Supporting Actor performance in Benh Zeitlin\'s Beasts of the Southern Wild spiritual successor, and in If Beale Street Could Talk (2018) as Fonny, a young Black artist unjustly imprisoned in 1970s New York. He crossed into blockbusters as the conspiracy-theorizing Godzilla podcaster Bernie Hayes in Godzilla vs. Kong (2021) and as the villainous Phastos in Eternals (2021). His film Causeway (2022) further showcased his heartbreaking dramatic range.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Dan Stevens', 'dan-stevens', 'Daniel Jonathan Stevens is a strikingly handsome, remarkably protean, and intellectually voracious British actor and author whose career has demonstrated a sustained commitment to subverting expectations at every turn — oscillating with deliberate creative restlessness between beloved romantic drama, surreal cult horror, prestige literary adaptation, and gleefully bombastic blockbuster spectacle. Born in 1982 in Croydon, South London, Stevens was adopted as an infant and educated at Tonbridge School in Kent, where he developed a passionate engagement with literature and performance before studying English at Emmanuel College, Cambridge. His professional theater career began with productions including The Doctor\'s Dilemma at the National Theatre. His global breakthrough arrived as the charming, principled Matthew Crawley in Julian Fellowes\' epoch-defining British period drama Downton Abbey (2010–2012), captivating worldwide audiences with his graceful portrayal of the first entry point of modernity into Edwardian aristocracy before controversially exiting the show. He immediately and deliberately dismantled that image by disappearing into the disquieting ambiguity of cult sci-fi horror The Guest (2014) as a deceptively charming former soldier of deeply sinister intentions, earning critical acclaim. He further transformed into the CGI-enhanced enchanted Beast in Disney\'s Beauty and the Beast (2017) opposite Emma Watson. As the Monarch veterinarian Trapper in Godzilla x Kong: The New Empire (2024), Stevens brought irreverent charm and kinetic comedy energy to the MonsterVerse\'s human dimension. His literary curiosity extends into authoring critically appreciated novels.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Naomi Watts', 'naomi-watts', 'Naomi Ellen Watts is a brilliantly courageous, emotionally fearless, and internationally acclaimed British-Australian actress of exceptional range and magnetic screen presence whose work across arthouse cinema, psychological thriller, drama, and blockbuster fantasy has consistently demonstrated a fearless commitment to inhabiting extreme emotional states with breathtaking authenticity and vulnerability. Born in 1968 in Shoreham, West Sussex, England, Watts moved to Australia as a teenager and began studying acting at the Australian Theatre for Young People before pursuing professional work across Australian television and film throughout the 1990s. Her career was transformed overnight by a single performance: the harrowing, emotionally shattering dual lead role in David Lynch\'s avant-garde mystery masterpiece Mulholland Drive (2001), where her portrayal of both the wide-eyed aspiring actress Betty and the broken, shattered Diane Selwyn earned universal critical acclaim and established her as one of cinema\'s boldest and most accomplished performers. Her portrayal earned Academy Award nominations for Best Actress for 21 Grams (2003) — Sean Penn\'s non-linear grief drama — and continued with devastating impact in J.U. Bayona\'s The Impossible (2012) as a tsunami survival story that demanded extraordinary physical and emotional endurance. As Ann Darrow in Peter Jackson\'s King Kong (2005), Watts brought remarkable emotional intelligence and physical grace to the role, creating a genuine wordless romance with the CGI Kong through pure expressive performance. Her continued work in television through HBO\'s Gypsy (2017), Netflix\'s Bly Manor (2020), and the Game of Thrones prequel series 3 Body Problem further demonstrates her extraordinary sustained artistry.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Andy Serkis', 'andy-serkis', 'Andrew Clement Serkis is a visionary, technically revolutionary, and deeply empathetic British actor, director, and performance capture pioneer whose extraordinary creative contributions have permanently transformed the boundaries of cinematic acting, effectively inventing and defining an entirely new dimension of the craft through his landmark motion capture performances that merge human emotional truth with digital visual technology. Born in 1964 in Ruislip, Middlesex, England, Serkis trained at Manchester Polytechnic\'s drama school before building a rich stage career across the Royal Shakespeare Company and various British theater productions. While his early television and film career was solid, nothing could have predicted the seismic revolution he would ignite in 2001 through his portrayal of Gollum in Peter Jackson\'s The Lord of the Rings: The Fellowship of the Ring — a physically transformed, psychologically fragmented creature of obsession and pathos brought to life through Serkis\'s full-body performance capture work combined with Weta Digital\'s digital character rendering. The performance was of such undeniable artistic depth and psychological complexity that debate erupted about whether Serkis deserved Academy Award recognition for a digitally rendered character — fundamentally challenging the Academy\'s understanding of what constitutes a film performance. He followed with an equally legendary performance as King Kong in Peter Jackson\'s 2005 remake, infusing the colossal gorilla with heartbreaking gentleness, savage rage, and wounded loneliness through thousands of hours of behavioral research and physical performance. He went on to create Caesar, the extraordinary chimpanzee protagonist of the Planet of the Apes trilogy. He also directed Mowgli: Legend of the Jungle (2018). An irreplaceable creative force in modern cinema.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();

