-- Title: Godzilla
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Godzilla', 'godzilla-2014', 'The world ends. He begins.', 'Godzilla is a thunderous, visually majestic monster epic directed by Gareth Edwards, reinventing cinema\'s greatest kaiju as a primordial, ancient balancing force of nature in a grounded, emotionally resonant blockbuster. The narrative opens in 1999 in the Philippines, where a colossal bone structure is excavated deep within a collapsed mine alongside two enormous fossilized spores — one dormant, one recently hatched. Simultaneously, a nuclear power plant in Janjira, Japan suffers catastrophic structural failure caused by mysterious underground tremors, killing the wife of engineer Joe Brody and traumatizing his son Ford. Fifteen years later, Ford Brody — now a Naval explosive ordinance disposal officer — returns to Japan after his estranged, obsessive father Joe is arrested while illegally investigating the quarantined Janjira plant. They discover the tremors were electromagnetic signals emitted by a massive, chrysalis-cocooned creature known as a MUTO — Massive Unidentified Terrestrial Organism — which feeds on radiation and has been secretly monitored by Monarch, a clandestine multinational scientific organization led by the enigmatic Dr. Ichiro Serizawa and Dr. Vivienne Graham. When the winged male MUTO erupts from Janjira and a colossal female MUTO awakens in Nevada, they set course for San Francisco to mate. But tracking their electromagnetic wake is Godzilla — an ancient alpha predator of immeasurable power that Monarch believes has existed since Earth\'s primordial era, drawn from the deep ocean to restore natural order by hunting the parasitic MUTOs. As Godzilla and the two MUTOs converge upon a devastated San Francisco in an apocalyptic nocturnal battle, Ford races through the chaos to disarm a nuclear warhead before it detonates. A spectacular tribute to kaiju cinema with breathtaking scope and an awe-inspiring monster reveal.', 'titles/posters/gz_godzilla_2014.jpg', '2014-05-16', 123, 'PG-13', 6.4, 160000000, 529076069, 'English', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
INSERT IGNORE INTO `genre_title` (`genre_id`, `title_id`) SELECT 1, `id` FROM `titles` WHERE `slug` = 'godzilla-2014';
INSERT IGNORE INTO `genre_title` (`genre_id`, `title_id`) SELECT 3, `id` FROM `titles` WHERE `slug` = 'godzilla-2014';
INSERT IGNORE INTO `genre_title` (`genre_id`, `title_id`) SELECT 9, `id` FROM `titles` WHERE `slug` = 'godzilla-2014';
