-- Title: Kong: Skull Island
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Kong: Skull Island', 'kong-skull-island-2017', 'All hail the king.', 'Kong: Skull Island is a thrilling, visually spectacular, and viscerally inventive monster adventure directed by Jordan Vogt-Roberts, boldly reinventing King Kong within the Legendary MonsterVerse as an island god of titanic proportions. Set in 1973 during the turbulent final chapter of the Vietnam War, the story follows Bill Randa, a tenacious government official from the classified Monarch organization, who manipulates a military Senate hearing to fund a covert geological survey expedition to the uncharted, perpetually storm-encircled Skull Island in the South Pacific. Assembled under the pretense of a seismic survey, the expedition includes the maverick British SAS tracker James Conrad, ambitious journalist Mason Weaver who suspects a government cover-up, and Lieutenant Colonel Preston Packard, a decorated, volatile Vietnam veteran commanding an elite helicopter squadron itching for one final mission. Upon breaching the perpetual hurricane barrier and deploying geological explosive charges across the island\'s surface, the expedition is immediately and catastrophically ambushed by the island\'s godlike alpha protector — Kong, a colossal gorilla standing nearly one hundred feet tall who decimates the fleet in a breathtaking, aerial onslaught sequence. Scattered across the dangerous, prehistoric ecosystem, the surviving parties must navigate a living mythology of giant spiders, colossal water buffaloes, and bioluminescent bamboo forests while encountering Hank Marlow, a stranded World War II pilot who has lived among the Iwi tribe for three decades. The island\'s true ecological hierarchy is exposed when Packard\'s obsessive revenge mission threatens to awaken the subterranean Skullcrawlers — voracious reptilian predators that are Kong\'s ancient nemesis and the island\'s greatest existential threat.', 'titles/posters/gz_kong_skull_island_2017.jpg', '2017-03-10', 118, 'PG-13', 6.6, 185000000, 566652812, 'English', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
INSERT IGNORE INTO `genre_title` (`genre_id`, `title_id`) SELECT 1, `id` FROM `titles` WHERE `slug` = 'kong-skull-island-2017';
INSERT IGNORE INTO `genre_title` (`genre_id`, `title_id`) SELECT 9, `id` FROM `titles` WHERE `slug` = 'kong-skull-island-2017';
