-- Title: Godzilla: King of the Monsters
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Godzilla: King of the Monsters', 'godzilla-king-of-the-monsters-2019', 'Long live the king.', 'Godzilla: King of the Monsters is an apocalyptic, mythologically rich, and visually thunderous MonsterVerse spectacle directed by Michael Dougherty, escalating the franchise into an era of Titan awakening and ancient ecological warfare. Five years after the catastrophic San Francisco battle between Godzilla and the MUTOs, the world has fractured between two ideological factions: the Monarch organization, which advocates for peaceful coexistence and scientific understanding of the Titans, and an eco-terrorist group led by the radicalized former Monarch scientist Alan Jonah, who believes humanity is a parasitic plague that only mass Titan awakening can cure. The Russell family — Dr. Emma Russell, a brilliant bioacoustics expert, and her estranged husband Dr. Mark Russell, a wildlife photography expert — are pulled into the maelstrom when Emma and their daughter Madison are abducted by Jonah\'s mercenaries. Using a bio-synthetic device called the ORCA that Emma designed to communicate with Titan bio-frequencies, Jonah and Emma trigger the global awakening of seventeen dormant Titans across the planet, including Mothra — the luminous, divine guardian insect Titan — the volcanic, aggressive pterosaur Titan Rodan, and most catastrophically, Monster Zero, better known as King Ghidorah, a three-headed, lightning-summoning extraterrestrial dragon of incalculable destructive power who immediately establishes himself as a usurper alpha. As Ghidorah dominates the Titans and drives global ecological devastation, Godzilla faces near-annihilation and must regenerate from nuclear depths to challenge the golden tyrant in a final cataclysmic showdown in Boston, with Madison\'s desperate ORCA gamble offering one final chance to alter the course of Titan history.', 'titles/posters/gz_godzilla_king_of_the_monsters_2019.png', '2019-05-31', 132, 'PG-13', 6, 170000000, 385900000, 'English', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
