-- Title: Godzilla vs. Kong
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Godzilla vs. Kong', 'godzilla-vs-kong-2021', 'One will fall.', 'Godzilla vs. Kong is the seismic, long-anticipated crown jewel of the Legendary MonsterVerse directed by Adam Wingard, delivering the definitive cinematic clash between cinema\'s two greatest monster titans in a spectacular globetrotting spectacle of apocalyptic proportions. In the wake of Godzilla\'s emergence as undisputed alpha Titan, the world\'s Titan population has retreated into uneasy coexistence — except Kong, who has been contained within an elaborate Skull Island biome habitat managed by Monarch scientists, including Dr. Ilene Andrews and her deaf adopted Iwi daughter Jia, who communicates with Kong through sign language. When Godzilla inexplicably launches a devastating, targeted attack on the Apex Cybernetics headquarters in Pensacola, Florida, Apex CEO Walter Simmons approaches Monarch with an audacious proposition: use Kong to lead an expedition into the Hollow Earth — the vast subterranean ecosystem beneath the Earth\'s crust — to locate an ancient power source that Apex needs to complete a classified, world-altering project. Simultaneously, Madison Russell, along with conspiracy theorist podcaster Bernie Hayes and friend Josh Valentine, infiltrates Apex\'s facility and discovers the horrifying truth behind Godzilla\'s aggression: Apex has secretly constructed Mechagodzilla, a cybernetically enhanced mechanical titan powered by the psychic neural link of a preserved Ghidorah skull, designed to eliminate all organic Titans and establish human dominance. As Kong descends into the magnificent bioluminescent depths of the Hollow Earth and discovers his ancestral throne room, Mechagodzilla breaks free and turns its devastating energy beam on both organic Titans. Kong and Godzilla must set aside their primordial rivalry in an electrifying Hong Kong finale to face their common mechanical nemesis.', 'titles/posters/gz_godzilla_vs_kong_2021.png', '2021-03-31', 113, 'PG-13', 6.3, 200000000, 468000000, 'English', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
