-- Title: Godzilla x Kong: The New Empire
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Godzilla x Kong: The New Empire', 'godzilla-x-kong-the-new-empire-2024', 'Rise together or fall alone.', 'Godzilla x Kong: The New Empire is an enormously entertaining, relentlessly kinetic, and visually audacious monster adventure directed by Adam Wingard, plunging deep into the vivid bioluminescent wonders of the Hollow Earth to unveil a civilization-threatening ancient evil that will require both Titans to set aside their differences and fight as one. Following the events of Godzilla vs. Kong, Kong has made the Hollow Earth his permanent home, roaming its magnificent prehistoric jungles as a solitary monarch while Godzilla restlessly circles the surface world, absorbing radiation and maintaining his position as Earth\'s supreme alpha Titan. Kong encounters startling archaeological evidence of an ancient, advanced civilization of ape-like Titans — the Kong-like Suko tribe — living in fear of a monstrous, tyrannical overlord known as the Skar King, a vicious, sadistic warlord who commands the Hollow Earth\'s ecosystem through brutal dominance and brandishes a crystalline energy whip crafted from the jagged teeth of his defeated enemies. The Skar King\'s most devastating weapon is Shimo, an enormous ancient Titan with the terrifying power to freeze and crystallize anything it touches — an ice-wielding beast of unimaginable destructive potential that the Skar King holds enslaved through a controlling crystal shard. On the surface, Monarch scientist Dr. Ilene Andrews receives escalating distress signals from the Hollow Earth through her bond with Jia, while Godzilla begins aggressively absorbing massive amounts of thermonuclear radiation, transforming into a glowing pink super-charged form. Recognizing that an unprecedented subterranean threat is about to breach the surface, Kong and Godzilla must form an uneasy but electrifying alliance to defeat the Skar King before Shimo triggers a new glacial extinction.', 'titles/posters/gz_godzilla_x_kong_the_new_empire_2024.jpg', '2024-03-29', 115, 'PG-13', 6.1, 135000000, 571686000, 'English', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
