-- Title: Godzilla
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Godzilla', 'godzilla-1954', 'The terror of the unknown.', 'Godzilla (1954) is the seminal, historically monumental, and emotionally devastating original Japanese kaiju masterpiece directed by Ishirō Honda, which not only launched the world\'s longest-running film franchise but stands as a profound, heartbreaking allegory for Japan\'s nuclear trauma, the destruction of Hiroshima and Nagasaki, and the terrifying psychological aftermath of the atomic age. When Japanese fishing vessels near Odo Island are suddenly incinerated and capsized by a mysterious, catastrophic force accompanied by massive flooding, investigators discover that the destruction matches no known natural phenomenon. A prehistoric, radioactively awakened leviathan — Godzilla — emerges from the depths of Tokyo Bay, making its first landfall in Tokyo during a harrowing nighttime rampage of incomprehensible scale, obliterating the city\'s infrastructure with atomic breath and thundering footsteps as civilians are incinerated in their tens of thousands. The narrative centers on Dr. Kyohei Yamane, a paleontologist who believes Godzilla must be studied rather than destroyed as a living relic of prehistory; his daughter Emiko; her fiancé, the disillusioned biologist Dr. Serizawa who has developed a terrifying and morally catastrophic secret weapon called the Oxygen Destroyer; and Naval officer Hideto Ogata, who loves Emiko. As Tokyo burns and the Japanese government debates military versus scientific response, the moral weight of deploying Serizawa\'s annihilation weapon — a device so powerful it could end all ocean life — forms the film\'s devastating ethical core. Honda\'s somber masterpiece gave voice to an entire generation\'s collective nuclear horror, creating cinema\'s most iconic monster as a metaphor for mankind\'s most dangerous invention.', 'titles/posters/gz_godzilla_1954.jpg', '1954-11-03', 96, 'Not Rated', 7.6, 175000, 2250000, 'Japanese', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
