-- Title: Mothra vs. Godzilla
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Mothra vs. Godzilla', 'mothra-vs-godzilla-1964', 'Beauty against beast.', 'Mothra vs. Godzilla, also released internationally as Godzilla vs. the Thing, is a thrilling, philosophically layered, and visually magnificent kaiju spectacle directed by Ishirō Honda, widely regarded as one of the finest and most thematically rich entries in the entire Toho Godzilla franchise and a crowning achievement of the classic Showa era. The narrative unfolds along Japan\'s Shizunoura coastline, where a devastating typhoon sweeps ashore a colossal, ornately decorated egg of unknown origin, which is immediately exploited by the unscrupulous, greedy businessman Kumayama and his corporate investor Torahata, who plan to monetize it as a novelty tourist attraction. Two diminutive twin fairy priestesses, the Shobijin, arrive from the sacred Infant Island to plead with the press and authorities for the egg\'s return to their goddess Mothra, warning that disturbing it will bring catastrophe. Simultaneously, radiation from the same coastal typhoon has awakened Godzilla from a beachside burial, and the ancient monster emerges to resume his destructive inland march. As Godzilla tears through Japan\'s cities, the desperate human delegation — led by journalist Ichiro Sakai and photographer Junko — travel to the ecologically ravaged, irradiated Infant Island to beg Mothra for assistance. Though the devastation wrought upon their island by nuclear testing makes the islanders distrust humanity, Mothra agrees to sacrifice herself in battle against Godzilla for the sake of global life. The climactic clash between the aging Mothra and the rampaging Godzilla is extraordinary in its mythological grandeur, and the emergence of the twin larval Mothras to carry on the battle is one of the franchise\'s most emotionally resonant and visually striking sequences. An enduring landmark of environmental mythology and poetic monster cinema.', 'titles/posters/gz_mothra_vs_godzilla_1964.jpg', '1964-04-29', 89, 'Not Rated', 6.9, 300000, 5000000, 'Japanese', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
