-- Title: Ghidorah, the Three-Headed Monster
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Ghidorah, the Three-Headed Monster', 'ghidorah-the-three-headed-monster-1964', 'Earth\'s greatest battle.', 'Ghidorah, the Three-Headed Monster is a thrilling, historically pivotal, and tonally inventive kaiju epic directed by Ishirō Honda that marks one of the most significant turning points in the entire Godzilla franchise — the radical transformation of Godzilla from humanity\'s greatest destructive terror into an unlikely, reluctant Earth protector, and the electrifying debut of King Ghidorah, the franchise\'s most iconic and catastrophically powerful villain. The complex narrative weaves together the mysterious arrival of Maliness Princess Salno, who survives an assassination attempt by inexplicably departing her royal aircraft moments before a bomb detonates and wandering Japan delivering manic, prophetic warnings of cosmic annihilation. She claims to be a Venusian prophetess warning that Ghidorah, the three-headed, magnetic-lightning-hurling space dragon that obliterated the civilization of Venus centuries ago, is inbound for Earth. Simultaneously, Rodan erupts from a volcanic caldera in Kyushu, while Godzilla resurfaces from the ocean to battle the self-styled king of the skies. The brilliant invention at the film\'s heart involves the twin Shobijin fairy priestesses translating a remarkable argument between Godzilla, Rodan, and Mothra — a genuinely comedic, warmly humanizing dialogue in which Mothra pleads with the proud, territorial Godzilla and Rodan to set aside their destructive individualism to unite against the extraterrestrial apocalyptic threat of Ghidorah. The climactic four-way battle on the slopes of Mt. Fuji — Godzilla, Rodan, and Mothra larva united against the golden, gravity-defying King Ghidorah — remains one of the most exhilarating ensemble monster battles in all kaiju cinema.', 'titles/posters/gz_ghidorah_the_three_headed_monster_1964.jpeg', '1964-12-20', 93, 'Not Rated', 6.8, 350000, 4500000, 'Japanese', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
