-- Title: Destroy All Monsters
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Destroy All Monsters', 'destroy-all-monsters-1968', 'Every monster that ever lived… in the most spectacular science fiction film ever made!', 'Destroy All Monsters is an epic, wildly imaginative, and gloriously maximalist science fiction kaiju ensemble blockbuster directed by Ishirō Honda, celebrating Toho\'s entire legendary monster pantheon in the grandest, most ambitious crossover event of the classic Showa era — a true cinematic monster summit that united nearly every iconic Titan in one spectacular, planet-saving adventure. Set in the futuristic year 1999, Earth\'s Titans have been peacefully contained on the remote, sealed Monsterland Reserve on Ogasawara Island — a scientifically managed habitat where Godzilla, Mothra, Rodan, Anguirus, Gorosaurus, Baragon, Varan, Kumonga, Manda, and Minilla coexist under Moonlight SY-3\'s watchful surveillance. When the reserve\'s communication systems go dark and the monsters mysteriously vanish from their habitat, investigators discover that the female Kilaak aliens — a militaristic extraterrestrial civilization — have infiltrated Monsterland\'s control facility and taken command of the Titans\' brains through embedded mind-control devices, deploying them simultaneously as weapons of global mass destruction against Earth\'s major cities: Godzilla attacks New York, Rodan lays waste to Moscow, Mothra destroys Peking, and Baragon strikes Paris. The Moonlight SY-3 crew traces the alien control signal and destroys the primary transmitter, liberating the monsters from alien domination. The Kilaaks retaliate by summoning King Ghidorah, their ultimate devastating weapon, igniting the film\'s stupendous, unforgettable climax at Mt. Fuji where all of Earth\'s liberated monsters converge to destroy Ghidorah simultaneously. An exhilarating, warm celebration of the entire Toho monster legacy.', 'titles/posters/gz_destroy_all_monsters_1968.jpg', '1968-08-01', 88, 'Not Rated', 6.5, 400000, 5200000, 'Japanese', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
