-- Title: King Kong vs. Godzilla
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('King Kong vs. Godzilla', 'king-kong-vs-godzilla-1962', 'The most colossal conflict the screen has ever known!', 'King Kong vs. Godzilla is the genre-defining, enormously entertaining, and historically monumental crossover spectacle directed by Ishirō Honda, uniting two of cinema\'s most towering and culturally iconic monster legends in the first — and for decades, only — meeting of the franchise titans, shattering Japanese box office records and becoming the most attended Godzilla film in Japanese history with over 11 million domestic tickets sold. The satirical narrative opens with the Pacific Pharmaceutical Company\'s ratings-hungry television executive Tako desperately seeking a sensational new entertainment property to revive flagging viewership. When rumors surface of a colossal ape-like creature worshipped as a god by the remote Faro Island inhabitants in the South Pacific, Tako dispatches a television crew to capture Kong for a global entertainment spectacle, inadvertently triggering a geopolitical monster collision of historic proportions. Meanwhile, the US Navy submarine Seahawk accidentally frees Godzilla from the Arctic glacier that imprisoned him in the last Showa film, and the resurrected leviathan immediately resumes his northward rampage across Japan. As Godzilla burns his way through Self-Defense Force positions and Kong — captured and sedated with Faro Island\'s addictive fermented berry juice — escapes his raft transport and battles Japanese military forces, the collision course between cinema\'s two supreme monsters becomes inevitable. The film\'s climactic Mt. Fuji showdown, featuring the memorable image of Kong grappling Godzilla in a lightning-fueled sumo wrestling match, is both absurd, exhilarating, and deeply satisfying — a joyful monster brawl that cemented the crossover formula still beloved today.', 'titles/posters/gz_king_kong_vs_godzilla_1962.jpg', '1962-08-11', 91, 'Not Rated', 6, 600000, 13000000, 'Japanese', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
