-- Title: Godzilla vs. Biollante
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Godzilla vs. Biollante', 'godzilla-vs-biollante-1989', 'The most beautiful monster ever born.', 'Godzilla vs. Biollante is the most emotionally complex, scientifically ambitious, and hauntingly beautiful entry in the entire Heisei Godzilla series, directed by Kazuki Ōmori, weaving Cold War espionage thriller, ethical bioengineering debate, and tragic parental grief into a monster narrative of unprecedented psychological depth. Following the catastrophic 1984 Tokyo battle against Godzilla, the Japanese government\'s Godzilla Prediction Network extracts cellular G-Cells from the monster\'s cooling trail — cells of extraordinary genetic resilience with potential military and agricultural applications. The G-Cells become the target of an international bioengineering arms race between Japan\'s SSS9 anti-G biological warfare unit, the sinister Saradia Oil States Corporation, and the ruthless international espionage network. Brilliant biogeneticist Dr. Genshiro Shiragami, consumed by grief over his daughter Erika\'s death in a terrorist bombing, has been secretly fusing her cellular DNA with a rose — the flower she most loved — to preserve her spirit within the living plant. When the Saradia Organization threatens to steal his G-Cell research, Shiragami makes the agonizing decision to splice Erika\'s gene-fused rose cells with Godzilla\'s G-Cells, creating Biollante — a magnificent, nightmarish, and heartbreakingly beautiful hybrid creature that manifests first as a colossal luminous rose and later transforms into a devastating, tentacled, acid-spitting leviathan. As Godzilla is lured from volcanic imprisonment back to Japan, the moral weight of Biollante\'s existence — a grieving father\'s love twisted into a monster — gives the climactic battle a tragic, Frankenstein-esque dimension. A genuinely unique and intellectually resonant achievement in monster cinema.', 'titles/posters/gz_godzilla_vs_biollante_1989.jpg', '1989-12-16', 104, 'Not Rated', 6.8, 6000000, 19500000, 'Japanese', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
