-- Title: Godzilla vs. Destoroyah
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Godzilla vs. Destoroyah', 'godzilla-vs-destoroyah-1995', 'The end of an era.', 'Godzilla vs. Destoroyah is the operatic, emotionally devastating, and mythologically resonant finale of the entire Heisei Godzilla series directed by Takao Okawara, delivering what many consider the most emotionally powerful and cinematically grand conclusion in the franchise\'s seventy-year history — the death of Godzilla — with the weight of a Greek tragedy and the scale of an apocalyptic epic. The film opens with the alarming discovery that Godzilla\'s nuclear heart is undergoing catastrophic runaway meltdown — his internal radiation has reached levels so extreme that his body is literally dissolving, emitting near-lethal radiation across Asia and threatening a global nuclear explosion of extinction-level proportions. Simultaneously, micro-organisms mutated by the Oxygen Destroyer weapon used against the original 1954 Godzilla have evolved across decades on the ocean floor, emerging as Destoroyah — a crustacean-derived aggregate monster of extraordinary ferocity that rapidly evolves through juvenile, aggregate, and terrifyingly powerful flying and perfect forms, possessing a microoxygen breath that can dissolve organic matter at the cellular level. As a glowing, overheating, heartbreakingly deteriorating Godzilla searches desperately across Asia for his estranged clone/son Godzilla Junior to transfer his life energy, the Japan Super-X III military aircraft races to cryogenically cool Godzilla enough to prevent the meltdown, while Miki Saegusa and Meru Ozawa lead the desperate effort to reunite father and son before the end. The film\'s climax — Godzilla\'s nuclear sacrifice, the death of Junior, and the heart-wrenching collapse of cinema\'s greatest monster icon — stands as one of cinema\'s most affecting creature-feature sequences. A magnificent, emotionally irreplaceable chapter of monster mythology.', 'titles/posters/gz_godzilla_vs_destoroyah_1995.jpg', '1995-12-09', 103, 'Not Rated', 7, 9000000, 30000000, 'Japanese', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
