-- Title: Shin Godzilla
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Shin Godzilla', 'shin-godzilla-2016', 'It is impossible to understand.', 'Shin Godzilla is a darkly satirical, politically electrifying, and visually audacious kaiju reimagining co-directed by Hideaki Anno and Shinji Higuchi, winner of seven Japan Academy Film Awards including Best Picture and Best Director — marking the first Godzilla film to win Japan\'s most prestigious cinematic honors and the most critically acclaimed Japanese giant monster film since the 1954 original. Rather than focusing on military spectacle or human adventure, Anno\'s singular creative vision delivers a bracingly incisive dissection of Japanese government bureaucracy, institutional paralysis, and post-disaster crisis management that functions simultaneously as monster cinema and scathing political satire. When Tokyo Bay erupts in violent geothermal upheaval and a previously unknown, grotesquely mutating living organism begins crawling ashore through Kamakura, the Japanese government\'s multi-layered committee system collapses into paralytic jurisdictional disputes, procedural deadlock, and bureaucratic comedy as officials desperately attempt to determine which ministry has authority over an unprecedented biological kaiju. The creature — evolving through increasingly horrifying forms — rapidly mutates into Godzilla: a towering, asymmetrical, malformed, radiation-emitting behemoth covered in grotesque gill-like slashes, with a disturbingly humanoid face and the most visually unsettling design in franchise history. Godzilla\'s atomic breath sequence in Shinjuku — a silent, blinding column of white heat that obliterates skyscrapers in an instant before he goes dormant — is widely regarded as the most terrifying and artistically striking Godzilla moment in the entire franchise. The human story centers on Deputy Chief Cabinet Secretary Rando Yaguchi, who assembles an unconventional interdisciplinary task force to defeat Godzilla before American tactical nuclear strikes obliterate Tokyo.', 'titles/posters/gz_shin_godzilla_2016.png', '2016-07-29', 120, 'Not Rated', 7.5, 15000000, 78000000, 'Japanese', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
