-- Title: Godzilla: Final Wars
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Godzilla: Final Wars', 'godzilla-final-wars-2004', 'The ultimate battle is here.', 'Godzilla: Final Wars is Toho\'s wildly exhilarating, unapologetically maximalist, and gloriously self-aware 50th anniversary monster extravaganza directed by Ryūhei Kitamura, unleashing an extraordinary, globe-spanning monster brawl that pits Godzilla against virtually every iconic Toho kaiju simultaneously in a frenetic, kung-fu-infused sci-fi action spectacle of breathless, unrelenting energy. Set in a future Earth where Titans have plagued civilization for decades, humanity has responded by creating the Earth Defense Force\'s M-Organization — an elite corps of genetically enhanced mutant soldiers capable of battling monsters in close combat. When multiple kaiju simultaneously attack cities across the globe — Rodan descends on New York, Anguirus targets Shanghai, Kamacuras attacks Paris, Ebirah strikes Sydney, Hedorah assaults Tokyo, and King Caesar battles Okinawa — the mysterious Xilien aliens suddenly arrive in gleaming flying saucers, seemingly using their advanced technology to dispatch all monsters simultaneously and presenting themselves as Earth\'s saviors. However, the Xilien offer of planetary partnership conceals a sinister plan of absorption and invasion. The mutant soldier Shinichi Ozaki and United Nations researcher Miyuki Otonashi uncover the Xilien conspiracy and make the audacious decision to wake Godzilla from his Antarctic imprisonment — unleashing the most powerful creature in Earth\'s history to battle through a gauntlet of monster after monster. What follows is cinema\'s greatest monster demolition derby as Godzilla systematically dismantles every Xilien-controlled kaiju in lightning-fast, borderline comedic succession before confronting the true threat. An adrenalized, joyful love letter to the entire Toho kaiju legacy.', 'titles/posters/gz_godzilla_final_wars_2004.jpg', '2004-12-04', 125, 'PG-13', 6, 19000000, 22000000, 'Japanese', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
