-- Title: King Kong
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('King Kong', 'king-kong-1933', 'The eighth wonder of the world.', 'King Kong (1933) is the legendary, eternally captivating, and artistically revolutionary adventure fantasy directed by Merian C. Cooper and Ernest B. Schoedsack that not only invented the giant monster movie genre and pioneered the art of special effects filmmaking but created one of cinema\'s most enduring, tragic, and emotionally resonant icons — a creature whose story of exploitation, longing, and doomed love continues to move audiences nearly a century after its creation. The adventure unfolds when ambitious, showman filmmaker Carl Denham assembles a crew aboard the ship Venture to sail to the uncharted Skull Island — a remote, perpetually fog-shrouded island inhabited by prehistoric creatures untouched by time. At the last moment, Denham recruits Ann Darrow, a beautiful, destitute young woman played by Fay Wray, as the female lead for his mysterious film project. Upon reaching Skull Island\'s native village, the tribe\'s witch doctor performs an elaborate sacrifice ceremony and kidnaps Ann, offering her as Bride of Kong — a colossal, seventeen-foot silverback gorilla who is simultaneously the island\'s supreme protector, its worshipped god, and its most fearsome and terrifying guardian. Kong carries Ann deep into the island\'s primeval jungles, where she witnesses the ancient creature fight off a Tyrannosaurus rex, a plesiosaur, and a pterodactyl with ferocious primal power. Carl Denham\'s crew pursue to rescue Ann and capture Kong with gas bombs, bringing him to New York for a sensational Broadway exhibition. The film\'s unforgettable finale atop the Empire State Building — where Kong clings to civilization\'s apex as biplanes circle — remains cinema\'s most iconic image of beauty, longing, and the tragedy of the wild imprisoned by human ambition.', 'titles/posters/gz_king_kong_1933.jpg', '1933-03-02', 100, 'Not Rated', 7.9, 670000, 10000000, 'English', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
