-- Title: King Kong
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('King Kong', 'king-kong-2005', 'The eighth wonder of the world.', 'King Kong (2005) is Peter Jackson\'s magnificent, sprawling, and deeply felt three-hour love letter to the 1933 original — a breathtaking technical achievement and emotionally rich adventure fantasy that brings Kong to life with unparalleled photorealism through Andy Serkis\'s legendary performance capture work and Weta Digital\'s then-revolutionary visual effects technology. Set in depression-era New York in 1933, the film follows vaudeville actress Ann Darrow, whose theatrical troupe dissolves in the economic desperation of the Great Depression. When ambitious, self-promoting filmmaker Carl Denham discovers that his funding has been pulled and his scheduled Pacific voyage will be cancelled, he impulsively recruits Ann and her favorite playwright Jack Driscoll, convincing the ship\'s captain to set sail for the uncharted Skull Island with a forged expedition permit. Upon anchoring off Skull Island\'s volcanic rock coastline, the crew ventures ashore to find an ancient, crumbling civilization wall separating the native village from the island\'s prehistoric interior — and the desperate, savage native population who kidnap Ann and offer her as a sacrifice to their island deity, Kong. What follows is Jackson\'s masterful command of pure cinematic spectacle: Ann\'s initial terror evolving into genuine, wordless communication with the lonely, magnificent Kong; the crew\'s harrowing rescue mission through a canyon of stampeding Brontosauri and a horrifying insect pit; Kong\'s brutal battles against multiple Tyrannosaurus rex atop a cascading waterfall while clutching Ann between his fingers. Captured and brought to Broadway as a carnival spectacle, Kong\'s heartbreaking awakening and desperate rampage through snowy Manhattan streets to find Ann culminates in the devastating, iconic Empire State Building finale. Andy Serkis\'s performance gives Kong extraordinary emotional depth.', 'titles/posters/gz_king_kong_2005.jpg', '2005-12-14', 187, 'PG-13', 7.2, 207000000, 550000000, 'English', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
